import grpc
from concurrent import futures
import smtplib
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
import re
import hashlib
import hmac
import os

# Proto-generated stubs simulated
class NotificationServiceServicer:
    pass

# Role definitions
ROLE_ADMIN = "admin"
ROLE_USER = "user"
ROLE_SERVICE = "service_account"

# Allowed roles for notification sending
ALLOWED_SENDER_ROLES = {ROLE_ADMIN, ROLE_SERVICE}

class EmailSanitizer:
    """Sanitizes email fields to prevent header injection."""

    HEADER_INJECTION_PATTERN = re.compile(r'[\r\n]')

    @staticmethod
    def sanitize_address(addr):
        """Remove any CRLF sequences from email addresses."""
        if EmailSanitizer.HEADER_INJECTION_PATTERN.search(addr):
            raise ValueError(f"Invalid characters in email address: {addr!r}")
        return addr.strip()

    @staticmethod
    def sanitize_subject(subject):
        """Remove any CRLF sequences from subject."""
        if EmailSanitizer.HEADER_INJECTION_PATTERN.search(subject):
            raise ValueError(f"Invalid characters in subject: {subject!r}")
        return subject.strip()

    @staticmethod
    def sanitize_display_name(name):
        """Sanitize display name for use in From/To headers."""
        if EmailSanitizer.HEADER_INJECTION_PATTERN.search(name):
            raise ValueError(f"Invalid characters in display name: {name!r}")
        return name.strip()


class AuthContext:
    """Extracts and validates authentication from gRPC metadata."""

    SECRET_KEY = os.environ.get('AUTH_SECRET')
    if not SECRET_KEY:
        raise RuntimeError(
            "AUTH_SECRET environment variable must be set to a strong secret; "
            "refusing to start with an insecure default."
        )

    @classmethod
    def from_metadata(cls, context):
        metadata = dict(context.invocation_metadata())
        token = metadata.get('authorization', '')
        if not token.startswith('Bearer '):
            return None
        token_body = token[7:]
        parts = token_body.split('.')
        if len(parts) != 3:
            return None
        # Simplified JWT-like validation
        payload_str = parts[1]
        signature = parts[2]
        expected_sig = hmac.new(
            cls.SECRET_KEY.encode(),
            (parts[0] + '.' + parts[1]).encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(signature, expected_sig):
            return None
        # Parse payload (simplified)
        import json, base64
        try:
            payload = json.loads(base64.b64decode(payload_str + '=='))
        except Exception:
            return None
        return cls(payload.get('sub'), payload.get('role'), payload.get('display_name', ''))

    def __init__(self, user_id, role, display_name):
        self.user_id = user_id
        self.role = role
        self.display_name = display_name


class NotificationService(NotificationServiceServicer):
    """gRPC service for sending notifications via email."""

    def __init__(self, smtp_host='localhost', smtp_port=25):
        self.smtp_host = smtp_host
        self.smtp_port = smtp_port
        self.sanitizer = EmailSanitizer()
        self.from_domain = "notifications.internal.corp"

    def _build_from_address(self, auth_context):
        """Construct the From address using authenticated user info."""
        # Service accounts use a fixed sender
        if auth_context.role == ROLE_SERVICE:
            return f"noreply@{self.from_domain}"
        # Admin users get their display name in the From header
        display = self.sanitizer.sanitize_display_name(auth_context.display_name)
        local_part = auth_context.user_id.replace('@', '_at_')
        return f"{display} <{local_part}@{self.from_domain}>"

    def _format_recipient_header(self, recipients, context_metadata):
        """Format the To header with optional display names from directory."""
        formatted = []
        for recip in recipients:
            addr = self.sanitizer.sanitize_address(recip.email)
            if recip.display_name:
                name = self.sanitizer.sanitize_display_name(recip.display_name)
                formatted.append(f"{name} <{addr}>")
            else:
                formatted.append(addr)
        return ", ".join(formatted)

    def SendNotification(self, request, context):
        """Main RPC handler for sending email notifications."""
        # Authentication
        auth = AuthContext.from_metadata(context)
        if auth is None:
            context.abort(grpc.StatusCode.UNAUTHENTICATED, "Invalid credentials")
            return

        # Authorization
        if auth.role not in ALLOWED_SENDER_ROLES:
            context.abort(grpc.StatusCode.PERMISSION_DENIED, 
                         f"Role '{auth.role}' not authorized to send notifications")
            return

        # Validate request
        if not request.recipients:
            context.abort(grpc.StatusCode.INVALID_ARGUMENT, "No recipients specified")
            return

        # Build email
        try:
            from_addr = self._build_from_address(auth)
            subject = self.sanitizer.sanitize_subject(request.subject)
            to_header = self._format_recipient_header(request.recipients, 
                                                      context.invocation_metadata())
        except ValueError as e:
            context.abort(grpc.StatusCode.INVALID_ARGUMENT, str(e))
            return

        # Construct MIME message
        msg = MIMEMultipart('alternative')
        msg['From'] = from_addr
        msg['To'] = to_header
        msg['Subject'] = subject
        msg['X-Mailer'] = 'InternalNotificationService/2.1'
        msg['X-Request-ID'] = self._extract_request_id(context)

        # Add body
        text_part = MIMEText(request.body_text, 'plain', 'utf-8')
        msg.attach(text_part)

        if request.body_html:
            html_part = MIMEText(request.body_html, 'html', 'utf-8')
            msg.attach(html_part)

        # Send
        try:
            self._send_smtp(msg, [r.email for r in request.recipients])
        except smtplib.SMTPException as e:
            context.abort(grpc.StatusCode.INTERNAL, f"SMTP error: {e}")
            return

        return NotificationResponse(success=True, message_id=msg['Message-ID'])

    def _extract_request_id(self, context):
        """Extract request ID from gRPC metadata for tracing."""
        metadata = dict(context.invocation_metadata())
        request_id = metadata.get('x-request-id', '')
        # Sanitize - allow alphanumeric, hyphens, and underscores only
        sanitized = re.sub(r'[^a-zA-Z0-9\-_]', '', request_id)
        return sanitized[:64] if sanitized else 'unknown'

    def _send_smtp(self, msg, recipient_addrs):
        """Send the constructed message via SMTP."""
        with smtplib.SMTP(self.smtp_host, self.smtp_port) as server:
            try:
                server.ehlo()
                if server.has_extn('starttls'):
                    server.starttls()
                    server.ehlo()
            except smtplib.SMTPException:
                # If STARTTLS negotiation fails, do not silently send in cleartext
                raise
            server.send_message(msg, to_addrs=recipient_addrs)


class NotificationResponse:
    def __init__(self, success, message_id):
        self.success = success
        self.message_id = message_id


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    service = NotificationService(
        smtp_host=os.environ.get('SMTP_HOST', 'mail.internal.corp'),
        smtp_port=int(os.environ.get('SMTP_PORT', '25'))
    )
    # add_NotificationServiceServicer_to_server(service, server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    serve()
